pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    DAO c;
    function setUp() public { c = new DAO(); }
    function testRegression_property() public {
        c.init(address(0x1), address(0x2), address(0x3));

        vm.prank(address(0x100));
        c.newAddressProposal(address(0x200), "DAO");

        vm.prank(address(0x100));
        c.voteProposal(1);

        vm.prank(address(0x100));
        c.newAddressProposal(address(0x300), "DAO");

        bool ok;
        try c.cancelProposal(1, 2) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(c.VAULT() != address(0));
    }
}
